/* Miracle-FW-I3 핸드북 데이터 (자동 생성) */
(window.HB_PACK=window.HB_PACK||{})["Miracle-FW-I3"]={"1": {"title": "Rapunzel", "vocab": [{"w": "child", "k": "아이", "d": "a young boy or girl", "s": [["You can have our child when she is born.", "child"], ["Give me your child, or die.", "child"], ["Long ago, a man and a woman want a child.", "child"]]}, {"w": "garden", "k": "정원", "d": "a place next to a house where flowers or vegetables grow", "s": [["The man goes into the witch’s garden at night.", "garden"], ["She is digging in her garden.", "garden"]]}, {"w": "catch", "k": "잡다", "d": "to take hold of someone so they cannot get away", "s": [["The witch catches him.", "catches"]]}, {"w": "be born", "k": "태어나다", "d": "to come into the world as a baby", "s": [["You can have our child when she is born.", "is born"], ["When the baby is born, they name her Rapunzel after the tree her mother loves.", "is born"]]}, {"w": "tall", "k": "높은", "d": "high from the bottom to the top", "s": [["The witch keeps Rapunzel in a small room in  a tall tower.", "tall"], ["The witch keeps Rapunzel in a small room in a tall tower.", "tall"]]}, {"w": "tower", "k": "탑", "d": "a tall, narrow building", "s": [["The witch keeps Rapunzel in a small room in  a tall tower.", "tower"], ["The witch keeps Rapunzel in a small room in a tall tower.", "tower"]]}, {"w": "golden", "k": "황금빛의", "d": "having the color of gold", "s": [["As Rapunzel grows older, her  golden hair gets longer and longer.", "golden"]]}, {"w": "year", "k": "해(1년)", "d": "a time of twelve months", "s": [["One day a few years later, Rapunzel is  singing when a prince goes by.", "years"], ["One day a few years later, Rapunzel is singing when a prince goes by.", "years"]]}, {"w": "later", "k": "후에", "d": "after some time", "s": [["One day a few years later, Rapunzel is  singing when a prince goes by.", "later"], ["One day a few years later, Rapunzel is singing when a prince goes by.", "later"]]}, {"w": "climb", "k": "오르다", "d": "to go up something using your hands and feet", "s": [["He will climb up to get her.", "climb"], ["He tried to climb the tree.", "climb"]]}], "sentences": [{"e": "Long ago, a man and a woman want a child.", "k": "옛날에 남자와 여자는 아이를 원했습니다."}, {"e": "When the baby is born, they name her Rapunzel after the tree her mother loves.", "k": "아이가 태어났을 때 그들은 엄마가 좋아하는 나무의 이름을 따서 Rapunzel이라는 이름을 지었습니다."}, {"e": "The witch keeps Rapunzel in a small room in a tall tower.", "k": "마녀는 높은 탑의 작은 방에 Rapunzel을 가둡니다."}, {"e": "One day a few years later, Rapunzel is singing when a prince goes by.", "k": "몇 년 후 어느 날 Rapunzel이 노래를 부르고 있을 때 왕자가 지나 갑니다."}, {"e": "She thinks it will help her have a baby."}, {"e": "Give me your child, or die."}, {"e": "There is only one window and one door."}, {"e": "Who is this girl who sings so well?"}, {"e": "You can have our child when she is born."}, {"e": "The prince hears her singing."}], "passage": ["Long ago, a man and a woman want a child. But they cannot have one. The wife asks the man to get her some of the rapunzel tree. She thinks it will help her have a baby. The man goes into the witch’s garden at night and takes some of her rapunzel tree. The witch catches him and says, “Give me your child, or die.” The man thinks of his wife but wants her to have a child. He says, “You can have our child when she is born.” When the baby is born, they name her Rapunzel after the tree her mother loves. They give Rapunzel to the witch.", "The witch keeps Rapunzel in a small room in a tall tower. There is only one window and one door. As Rapunzel grows older, her golden hair gets longer and longer. She loves to sing. One day a few years later, Rapunzel is singing when a prince goes by. The prince hears her singing. He thinks, “Who is this girl who sings so well?” He sees Rapunzel in the window. He falls in love. The prince tells Rapunzel to put her hair out of the window, and he will climb up to get her."], "qa": [["What do a man and woman want?", "A child"], ["What does the wife ask the man to get her?", "Some of the rapunzel tree"], ["Where does the man go?", "He goes into the witch’s garden."], ["What happens to the man?", "The witch catches him."], ["What does the witch say to the man?", "“Give me your child, or die.”"], ["What do they name the baby?", "They name her Rapunzel."], ["What do they do with the baby?", "They give her to the witch."], ["Where does the witch keep Rapunzel?", "In a small room in a tall tower"], ["What gets very long?", "Rapunzel’s hair"], ["What does Rapunzel like to do?", "She likes to sing."], ["What does the prince hear?", "He hears Rapunzel singing."], ["What does the prince want to know?", "Who the girl is"], ["What does the prince tell Rapunzel to do?", "To put her hair out of the window"]], "ox": [["A man and a woman want a child.", true], ["The man goes into the witch’s garden in the morning.", false], ["The witch catches the man.", true], ["The witch keeps Rapunzel in a big house.", false], ["Rapunzel loves to sing.", true], ["The prince hears Rapunzel singing.", true]]}, "2": {"title": "Rapunzel", "vocab": [{"w": "beautiful", "k": "아름다운", "d": "very nice to look at or listen to", "s": [["He is trying to find the girl with the beautiful voice.", "beautiful"], ["When the prince gets into the room, he sees the beautiful girl with the witch.", "beautiful"]]}, {"w": "witch", "k": "마녀", "d": "a woman in stories who uses magic to do bad things", "s": [["The witch makes him blind.", "witch"], ["When the prince gets into the room, he sees the beautiful girl with the witch.", "witch"], ["The witch is now dead, and Rapunzel now lives with her father and mother.", "witch"]]}, {"w": "again", "k": "다시", "d": "one more time", "s": [["You will never see Rapunzel again.", "again"], ["Her tears make him see again.", "again"]]}, {"w": "blind", "k": "눈이 먼", "d": "not able to see", "s": [["The witch makes him blind.", "blind"]]}, {"w": "month", "k": "달(개월)", "d": "one of the twelve parts of a year", "s": [["For many months, he walks all over the country.", "months"], ["December is the last month of the year.", "month"]]}, {"w": "country", "k": "나라", "d": "a land with its own people and government", "s": [["For many months, he walks all over the country.", "country"], ["Russia is the largest country in the world.", "country"]]}, {"w": "find", "k": "찾다", "d": "to see or get something you were looking for", "s": [["He is trying to find the girl with the beautiful voice.", "find"], ["One day, he finds her in a small town in the mountains.", "finds"], ["Rapunzel sings every day so he will find her.", "find"]]}, {"w": "voice", "k": "목소리", "d": "the sound you make when you speak or sing", "s": [["He is trying to find the girl with the beautiful voice.", "voice"]]}, {"w": "town", "k": "마을", "d": "a place where people live, smaller than a city", "s": [["One day, he finds her in a small town in the mountains.", "town"]]}, {"w": "tear", "k": "눈물", "d": "a drop of water that comes from your eye when you cry", "s": [["Her tears make him see again.", "tears"]]}], "sentences": [{"e": "Rapunzel sings every day so he will find her.", "k": "Rapunzel은 그가 그녀를 찾을 수 있게 매일 노래합니다."}, {"e": "One day, he finds her in a small town in the mountains.", "k": "어느 날 그는 산속의 작은 마을에서 그녀를 찾습니다."}, {"e": "Rapunzel cries when she sees the prince.", "k": "Rapunzel은 왕자를 보고 웁니다."}, {"e": "Her tears make him see again.", "k": "그녀의 눈물이 그를 다시 보게 합니다."}, {"e": "When the prince gets into the room, he sees the beautiful girl with the witch."}, {"e": "You will never see Rapunzel again."}, {"e": "The witch makes him blind."}, {"e": "The witch is now dead, and Rapunzel now lives with her father and mother."}, {"e": "Rapunzel is mine."}, {"e": "They live happily ever after."}], "passage": ["When the prince gets into the room, he sees the beautiful girl with the witch. The witch says, “Rapunzel is mine. You will never see Rapunzel again.” The witch makes him blind. For many months, he walks all over the country trying to find the girl with the beautiful voice. Rapunzel sings every day so he will find her. One day, he finds her in a small town in the mountains. The witch is now dead, and Rapunzel now lives with her father and mother. Rapunzel cries when she sees the prince. Her tears make him see again. They live happily ever after."], "qa": [["Who does the prince see in the room?", "He sees Rapunzel and the witch."], ["What does the witch do to the prince?", "She makes him blind."], ["Why does the witch do that?", "So the prince will never see Rapunzel again"], ["What does the prince do?", "He walks all over the country to find Rapunzel."], ["Why does Rapunzel sing every day?", "So the prince will find her"], ["Where does the prince find her?", "In a small town in the mountains."], ["What does Rapunzel do when she sees the prince?", "She cries."], ["What makes the prince see again?", "Rapunzel’s tears"]], "ox": [["The witch makes the prince blind.", true], ["The prince stops looking for Rapunzel.", false], ["Rapunzel sings every day so the prince will find her.", true], ["The prince finds Rapunzel in a big city.", false], ["Rapunzel’s tears make the prince see again.", true]]}, "3": {"title": "The Three Dogs", "vocab": [{"w": "fight", "k": "싸우다", "d": "to try to hurt or beat someone", "s": [["He can fight for you.", "fight"]]}, {"w": "break", "k": "깨다", "d": "to make something go into pieces", "s": [["He can break rocks.", "break"]]}, {"w": "hungry", "k": "배고픈", "d": "wanting or needing food", "s": [["I am hungry.", "hungry"]]}, {"w": "have to", "k": "–해야 한다", "d": "must do something", "s": [["I have to give her to a dragon.", "have to"]]}, {"w": "follow", "k": "따라가다", "d": "to go after someone", "s": [["John follows the girl and the man to a hill.", "follows"]]}, {"w": "hill", "k": "언덕, 낮은 산", "d": "a high area of land, smaller than a mountain", "s": [["John follows the girl and the man to a hill.", "hill"], ["A dragon lives on the hill!", "hill"]]}, {"w": "because", "k": "–때문에", "d": "for the reason that", "s": [["Say it is dead because of me!", "because"], ["I cried because I had hurt my knee.", "because"]]}, {"w": "throw", "k": "던지다", "d": "to send something through the air with your hand", "s": [["Say this, or I will throw you in the river!", "throw"]]}, {"w": "river", "k": "강", "d": "a long line of water that flows to the sea", "s": [["Say this, or I will throw you in the river!", "river"]]}, {"w": "afraid", "k": "겁내는", "d": "feeling scared", "s": [["The girl is afraid, so she says, “OK.”", "afraid"], ["Animals are usually afraid of fire.", "afraid"]]}], "sentences": [{"e": "One day, John meets an old man with three dogs.", "k": "어느 날 John은 세 마리의 개를 데리고 있는 노인을 만납니다."}, {"e": "Salt gets food for John!", "k": "Salt는 John을 위해 음식을 가져옵니다!"}, {"e": "John follows the girl and the man to a hill.", "k": "John은 소녀와 남자를 따라 언덕으로 갑니다."}, {"e": "Pepper kills the dragon.", "k": "Pepper가 용을 죽입니다."}, {"e": "Do you want these dogs for your sheep?"}, {"e": "I will meet you again in one year."}, {"e": "Tell the king the dragon is dead."}, {"e": "Next year, you can marry her."}, {"e": "A dragon lives on the hill!"}, {"e": "My daughter is young now."}], "passage": ["John has three sheep. One day, John meets an old man with three dogs. “Do you want these dogs for your sheep?” asks the man. “Salt is the small dog,” says the man. “He can get food for you. Pepper is the next one. He can fight for you. Mustard is the big one. He can break rocks.” John takes the dogs. He says, “I am hungry. Salt, get some food for me.” Salt gets food for John! The next day, John sees a sad girl. “Why is she crying?” asks John. “She is the king’s daughter. I have to give her to a dragon,” says a man. John follows the girl and the man to a hill. A dragon lives on the hill! “Pepper, fight the dragon!” says John. Pepper kills the dragon.", "“Thank you!” says the girl. She wants John to marry her. “I can’t go with you now,” says John. He says, “I will meet you again in one year.” On the way home, the man stops with the girl. “The boy is not here now,” says the man. “Tell the king the dragon is dead,” he says. “Say it is dead because of me! Say this, or I will throw you in the river!” The girl is afraid, so she says, “OK.” “Thank you for killing the dragon,” says the king. “My daughter is young now. Next year, you can marry her.” The man is very happy. The girl is very sad."], "qa": [["What does John have?", "He has three sheep."], ["What can Salt do?", "He can get food."], ["Who does John meet?", "A man with three dogs"], ["What can Mustard do?", "He can break rocks."], ["What does John do with the dogs?", "He takes them."], ["Who gets John food?", "Salt"], ["Who does John see?", "He sees a sad girl."], ["Why is the girl sad?", "A man has to give her to a dragon."], ["Where do they all go?", "To the hill where the dragon lives"], ["How does Pepper help?", "He kills the dragon."], ["What does the girl want?", "She wants to marry John."], ["When will John and the girl meet again?", "In one year"], ["What does the man want the girl to tell the king?", "That the dragon is dead because of him"], ["Why does the girl say “OK”?", "Because she is afraid"], ["Who will marry the girl?", "The man"], ["Does the girl want to marry the man?", "No, she doesn’t. She is very sad."]], "ox": [["John has three sheep.", true], ["Salt can break rocks.", false], ["Pepper can fight for John.", true], ["The girl is the king’s daughter.", true], ["Mustard kills the dragon.", false], ["The girl says OK because she is afraid.", true]]}, "4": {"title": "The Three Dogs", "vocab": [{"w": "after", "k": "뒤에(후에)", "d": "later than something", "s": [["After one year, John comes.", "After"], ["I felt tired after work.", "after"]]}, {"w": "true", "k": "사실인", "d": "not false; real", "s": [["That is not true.", "true"]]}, {"w": "need", "k": "필요하다", "d": "to must have something", "s": [["John needs his dog’s help.", "needs"]]}, {"w": "wall", "k": "벽", "d": "the side of a room or building", "s": [["Mustard breaks the wall.", "wall"]]}, {"w": "about", "k": "–에 대한", "d": "on the subject of", "s": [["The girl tells the king about John and  the dragon.", "about"], ["The girl tells the king about John and the dragon.", "about"]]}, {"w": "marry", "k": "결혼하다", "d": "to become someone’s husband or wife", "s": [["John marries the king’s daughter.", "marries"]]}, {"w": "daughter", "k": "딸", "d": "a person’s girl child", "s": [["John marries the king’s daughter.", "daughter"]]}, {"w": "work", "k": "일", "d": "a job or something you must do", "s": [["Our work for you is over.", "work"], ["I felt tired after work.", "work"]]}, {"w": "over", "k": "끝이 난", "d": "finished", "s": [["Our work for you is over.", "over"]]}, {"w": "change into", "k": "–으로 바뀌다", "d": "to become something different", "s": [["The three dogs change into birds.", "change into"], ["Caterpillars change into butterflies.", "change into"]]}], "sentences": [{"e": "The king puts John in a small room.", "k": "왕이 John을 작은 방에 넣습니다."}, {"e": "Mustard breaks the wall.", "k": "Mustard가 벽을 깹니다."}, {"e": "The girl tells the king about John and the dragon.", "k": "소녀는 왕에게 John과 용에 대해 말합니다."}, {"e": "The three dogs change into birds.", "k": "세 마리의 개가 새들로 바뀝니다."}, {"e": "The dragon is dead because of me."}, {"e": "John needs his dog’s help."}, {"e": "She is happy to see John."}, {"e": "The king puts the bad man in a small room."}, {"e": "That is not true."}, {"e": "Our work for you is over."}], "passage": ["After one year, John comes. “The dragon is dead because of me,” John says to the king. “That is not true,” says the king. The king puts John in a small room. John needs his dog’s help. “Mustard, break the wall!” says John to his dog. Mustard breaks the wall. John finds the girl. She is happy to see John. The girl tells the king about John and the dragon. The king puts the bad man in a small room. John marries the king’s daughter. “Our work for you is over,” says Mustard to John. The three dogs change into birds. They fly away."], "qa": [["Where does the king put John?", "In a small room"], ["Why does the king put John in a small room?", "He thinks John is not telling the truth."], ["How does Mustard help?", "Mustard breaks the wall."], ["How does the girl feel to see John?", "She is happy."], ["Where does the king put the bad man?", "In a small room"], ["Who does the girl marry?", "John"], ["What do the dogs change into?", "They change into birds."], ["Why do they change into birds?", "Their work for John is done."]], "ox": [["John comes back after one year.", true], ["The king believes John at first.", false], ["Mustard breaks the wall.", true], ["John marries the king’s daughter.", true], ["The three dogs change into horses.", false]]}, "5": {"title": "The King and His Clothes", "vocab": [{"w": "weaver", "k": "(천 등을) 짜는 사람", "d": "a person who makes cloth", "s": [["A weaver sees the king.", "weaver"], ["The king sends his servant to the weaver.", "weaver"]]}, {"w": "idea", "k": "생각, 계획", "d": "a thought or a plan", "s": [["I have an idea.", "idea"]]}, {"w": "trick", "k": "속임수", "d": "something you do to fool someone", "s": [["I can play a trick on the king and  get a lot of money.", "trick"]]}, {"w": "special", "k": "특별한", "d": "different from others and very good", "s": [["I need a lot of gold to make these clothes  because they are very special.", "special"], ["I need a lot of gold to make these clothes because they are very special.", "special"]]}, {"w": "fool", "k": "바보", "d": "a person who is not wise", "s": [["Fools cannot see these clothes.", "Fools"], ["I cannot tell the king I am a fool.", "fool"]]}, {"w": "invisible", "k": "보이지 않는", "d": "not able to be seen", "s": [["They think these clothes are invisible.", "invisible"]]}, {"w": "worried", "k": "걱정하는", "d": "feeling afraid that something bad may happen", "s": [["A few days later, the king is worried.", "worried"], ["You look worried. What’s the matter?", "worried"]]}, {"w": "send", "k": "보내다", "d": "to make something or someone go to a place", "s": [["The king sends his servant to the weaver.", "sends"], ["I will send a letter to my mom.", "send"]]}, {"w": "servant", "k": "하인", "d": "a person who works in another person’s house", "s": [["The king sends his servant to the weaver.", "servant"], ["The servant cannot see the clothes because there are no clothes.", "servant"], ["The servant tells the king the clothes are wonderful.", "servant"]]}, {"w": "show", "k": "보여주다", "d": "to let someone see something", "s": [["I will show everybody these clothes.", "show"]]}], "sentences": [{"e": "This is a story about a king who loves clothes.", "k": "이 이야기는 옷을 사랑하는 왕에 대한 이야기입니다."}, {"e": "A few days later, the king is worried.", "k": "며칠 후 왕은 걱정합니다."}, {"e": "The servant cannot see the clothes because there are no clothes.", "k": "하인은 옷이 없기 때문에 옷을 볼 수 없습니다."}, {"e": "The servant tells the king the clothes are wonderful.", "k": "하인은 왕에게 옷이 아주 멋지다고 말합니다."}, {"e": "I need a lot of gold to make these clothes because they are very special."}, {"e": "They think these clothes are invisible."}, {"e": "I cannot tell the king I am a fool."}, {"e": "I will show everybody these clothes."}, {"e": "Everybody likes his clothes."}, {"e": "Fools cannot see these clothes."}], "passage": ["This is a story about a king who loves clothes. The king walks in the town. Everybody likes his clothes. The king is very happy. A weaver sees the king. “I have an idea,” he thinks. “I can play a trick on the king and get a lot of money.” The next day, the weaver comes to see the king. He says, “I’m a weaver. I make wonderful clothes.” “Make me your best clothes,” says the king. “That is not easy,” says the weaver. “I need a lot of gold to make these clothes because they are very special.” “Why?” asks the king.", "“These clothes will tell you who is a fool. Fools cannot see these clothes. They think these clothes are invisible.” The king likes this idea. “Now I can know who is a fool,” he thinks. “Make me these clothes,” he says. A few days later, the king is worried. He thinks, “A fool can’t see the clothes. Will I see the clothes?” The king sends his servant to the weaver. The servant cannot see the clothes because there are no clothes. The servant thinks, “Oh no! I’m a fool. I cannot tell the king I am a fool.” The servant tells the king the clothes are wonderful. The king is very happy. “I will show everybody these clothes,” he says."], "qa": [["What is this story about?", "A king who loves clothes"], ["Why is the king happy?", "Everybody likes his clothes."], ["What is the weaver’s idea?", "To play a trick on the king to get a lot of money"], ["What does the king want the weaver to do?", "Make him the best clothes"], ["What does the weaver need to make the special clothes?", "He needs a lot of gold."], ["What can the clothes do?", "Tell the king who is a fool"], ["What do fools think about the clothes?", "Fools can’t see them and think they are invisible."], ["Why does the king want the clothes?", "So he can know who is a fool"], ["Why is the king worried?", "He is worried if he will see the clothes."], ["Why does the servant not see the clothes?", "There are no clothes."], ["What does the servant think about himself?", "The servant thinks he’s a fool."], ["What does the servant tell the king about the clothes?", "He says they are wonderful."], ["What will the king do with his new clothes?", "He will show everybody."]], "ox": [["The king loves clothes.", true], ["The weaver wants to play a trick on the king.", true], ["The weaver needs a lot of silver.", false], ["Fools cannot see the clothes.", true], ["The servant can see the clothes.", false]]}, "6": {"title": "The King and His Clothes", "vocab": [{"w": "clothes", "k": "옷", "d": "things you wear, like shirts and pants", "s": [["The clothes are wonderful.", "clothes"], ["He thinks he is wearing his new clothes.", "clothes"], ["The people know he has no clothes on.", "clothes"]]}, {"w": "wonderful", "k": "아주 멋진", "d": "very good", "s": [["The clothes are wonderful.", "wonderful"], ["The king’s clothes are wonderful!", "wonderful"]]}, {"w": "smile", "k": "미소 짓다", "d": "to make a happy face", "s": [["The weaver smiles and thinks, “My  trick is working.”", "smiles"]]}, {"w": "work", "k": "(계획 등이) 잘 되어 가다", "d": "a job or something you must do", "s": [["The weaver smiles and thinks, “My  trick is working.”", "working"], ["My trick is working.", "working"]]}, {"w": "wear", "k": "입고 있다", "d": "to have clothes on your body", "s": [["He thinks he is wearing his new clothes.", "wearing"], ["I want to wear those pants.", "wear"], ["The king is wearing no clothes.", "wearing"]]}, {"w": "people", "k": "사람들", "d": "men, women, and children", "s": [["The people know he has no clothes on.", "people"], ["But I cannot tell people I’m a fool.", "people"], ["The people know he has no clothes on, but they want him to be happy.", "people"]]}, {"w": "know", "k": "알다", "d": "to have something in your mind", "s": [["The people know he has no clothes on.", "know"], ["The people know he has no clothes on, but they want him to be happy.", "know"]]}, {"w": "handsome", "k": "멋진", "d": "good-looking (usually for a man)", "s": [["He looks so handsome!", "handsome"]]}, {"w": "everybody", "k": "모두", "d": "all the people", "s": [["Then everybody laughs at the king.", "everybody"], ["I love to make everybody happy.", "everybody"]]}, {"w": "laugh", "k": "(소리내어) 웃다", "d": "to make sounds because something is funny", "s": [["Then everybody laughs at the king.", "laughs"]]}], "sentences": [{"e": "But the king cannot see the invisible clothes.", "k": "그러나 왕은 보이지 않는 옷을 볼 수 없습니다."}, {"e": "He thinks he is wearing his new clothes.", "k": "그는 자신이 새 옷을 입고 있다고 생각합니다."}, {"e": "The people know he has no clothes on, but they want him to be happy.", "k": "사람들은 그가 옷을 입지 않았다는 것을 알지만 그가 행복하기를 바랍니다."}, {"e": "Then everybody laughs at the king.", "k": "그러자 모두가 왕을 보고 웃습니다."}, {"e": "But I cannot tell people I’m a fool."}, {"e": "The king walks in the town."}, {"e": "The king’s clothes are wonderful!"}, {"e": "The king’s face is red."}, {"e": "My trick is working."}, {"e": "The king is wearing no clothes."}], "passage": ["The weaver goes to the king. “Here are the clothes,” he says. But the king cannot see the invisible clothes. He thinks, “Oh no, I’m a fool. But I cannot tell people I’m a fool.” The king says to the weaver, “The clothes are wonderful.” The weaver smiles and thinks, “My trick is working.” The king walks in the town. He thinks he is wearing his new clothes. The people know he has no clothes on, but they want him to be happy. They say, “The king’s clothes are wonderful! Oh my! He looks so handsome!” The king is very happy. A small boy sees the king. The small boy says, “Look! The king is wearing no clothes.” Then everybody laughs at the king. The king’s face is red."], "qa": [["What can the king not see?", "He cannot see the invisible clothes."], ["Why does the king tell the weaver the clothes are wonderful?", "He doesn’t want people to think he is a fool."], ["Why is the weaver happy?", "His trick is working."], ["What does the king think he is wearing?", "His new special clothes"], ["What do the people say about the king?", "They say his clothes are wonderful and he looks handsome."], ["Is the king wearing wonderful clothes?", "No, he is not wearing clothes."], ["Who says the king is not wearing clothes?", "A small boy"], ["What do the people do?", "They laugh at the king."]], "ox": [["The king cannot see the invisible clothes.", true], ["The king tells people he is a fool.", false], ["The weaver thinks his trick is working.", true], ["A small girl says the king is wearing no clothes.", false], ["Everybody laughs at the king.", true]]}, "8": {"title": "How the Rhinoceros Got His Skin", "vocab": [{"w": "skin", "k": "피부, 가죽", "d": "the outer layer of a body", "s": [["How the Rhinoceros Got His Skin", "Skin"]]}, {"w": "beach", "k": "해변", "d": "the sandy land next to the sea", "s": [["Long ago, a man lived on a beach.", "beach"]]}, {"w": "stove", "k": "(요리용) 화로", "d": "a thing you use to cook or bake food", "s": [["The other things were a fork and stove.", "stove"], ["The other things were a fork and a stove.", "stove"], ["Every day, he baked a cake in the stove.", "stove"]]}, {"w": "collect", "k": "모으다", "d": "to bring things together", "s": [["He collected the ingredients.", "collected"]]}, {"w": "ingredient", "k": "재료", "d": "one of the foods you use to make a dish", "s": [["He collected the ingredients.", "ingredients"], ["She uses the best ingredients in her cooking.", "ingredients"]]}, {"w": "scared", "k": "겁먹은", "d": "feeling afraid", "s": [["The man was scared.", "scared"]]}, {"w": "run away", "k": "도망치다", "d": "to leave a place quickly to escape", "s": [["He ran away and climbed up a tree.", "ran away"]]}, {"w": "delicious", "k": "아주 맛있는", "d": "tasting very good", "s": [["It was delicious!", "delicious"], ["Who cooked this? It is delicious.", "delicious"]]}, {"w": "leave", "k": "남기다", "d": "to let something stay in a place", "s": [["He left only crumbs.", "left"]]}, {"w": "crumb", "k": "부스러기", "d": "a very small piece of bread or cake", "s": [["He left only crumbs.", "crumbs"]]}], "sentences": [{"e": "He collected the ingredients.", "k": "그는 재료를 모았습니다."}, {"e": "He mixed together flour, raisins, plums, and sugar.", "k": "그는 밀가루, 건포도, 자두, 설탕을 같이 섞었습니다."}, {"e": "Just then, a rhinoceros walked by.", "k": "바로 그때, 코뿔소가 지나갔습니다."}, {"e": "He ran away and climbed up a tree.", "k": "그는 도망쳐 나무 위로 올라갔습니다."}, {"e": "The other things were a fork and a stove."}, {"e": "Every day, he baked a cake in the stove."}, {"e": "That rhinoceros always eats my cake."}, {"e": "He will not eat my cakes again!"}, {"e": "It was delicious!"}, {"e": "He left only crumbs."}], "passage": ["Long ago, a man lived on a beach. He had only three things. One thing was a big yellow sun hat. The other things were a fork and a stove. Every day, he baked a cake in the stove. One day, the man was hungry. It was time to bake a cake. He collected the ingredients. He mixed together flour, raisins, plums, and sugar. Then he baked the cake in the stove. What a beautiful cake! Just then, a rhinoceros walked by. He smelled the cake. The cake smelled good. “Boo!” said the rhinoceros. The man was scared. He ran away and climbed up a tree. The rhinoceros found the cake. It was delicious! The rhinoceros ate all the cake. He left only crumbs. The man was angry. “That rhinoceros always eats my cake,” he said. “I want to eat my cakes. I will teach that rhino. He will not eat my cakes again!”"], "qa": [["Where did the man live?", "He lived on a beach."], ["What did the man have?", "He had a yellow sun hat, a fork, and a stove."], ["What did the man do every day?", "He baked a cake in the stove."], ["What did the man do first to make the cake?", "He collected the ingredients."], ["What did the man mix together?", "Flour, raisins, plums, and sugar"], ["How was the cake?", "It was beautiful."], ["What walked by?", "A rhinoceros"], ["Why did the man climb up a tree?", "He was scared of the rhinoceros."], ["What did the rhinoceros do to the cake?", "He ate it all and left only crumbs."], ["How did the man feel?", "He was angry."], ["Why was he angry?", "The rhinoceros ate his cake."]], "ox": [["The man had a big yellow sun hat.", true], ["The man baked a cake every day.", true], ["The rhinoceros was scared of the man.", false], ["The man climbed up a tree.", true], ["The rhinoceros left half of the cake.", false]]}, "9": {"title": "How the Rhinoceros Got His Skin", "vocab": [{"w": "take off", "k": "벗다", "d": "to remove clothes from your body", "s": [["He took off his skin.", "took off"]]}, {"w": "hang", "k": "걸다", "d": "to put something up so it does not touch the ground", "s": [["I helped her hang the picture on the wall.", "hang"]]}, {"w": "steal", "k": "훔치다", "d": "to take something that is not yours", "s": [["The man stole the rhinoceros’s skin.", "stole"]]}, {"w": "plan", "k": "계획", "d": "an idea of what you will do", "s": [["I have a plan.", "plan"]]}, {"w": "wrinkled", "k": "주름이 있는", "d": "having many small lines", "s": [["Soon the skin was wrinkled.", "wrinkled"], ["Even now, every rhinoceros is angry and has wrinkled skin.", "wrinkled"]]}, {"w": "put on", "k": "–을 입다", "d": "to put clothes on your body", "s": [["The rhinoceros finished swimming  and put on his skin again.", "put on"], ["The rhinoceros finished swimming and put on his skin again.", "put on"]]}, {"w": "tickle", "k": "간질이다", "d": "to make someone laugh by touching them lightly", "s": [["Why did it tickle?", "tickle"]]}, {"w": "scratch", "k": "긁다", "d": "to rub your skin with your nails", "s": [["He scratched his skin.", "scratched"], ["The cat will scratch you with its claws.", "scratch"]]}, {"w": "roll", "k": "구르다", "d": "to turn over and over", "s": [["He rolled in the sand.", "rolled"]]}, {"w": "different", "k": "다른", "d": "not the same", "s": [["He lives on a different beach now.", "different"]]}], "sentences": [{"e": "The man stole the rhinoceros’s skin.", "k": "그 남자는 코뿔소의 가죽을 훔쳤습니다."}, {"e": "He scratched his skin.", "k": "그는 그의 피부를 긁었습니다."}, {"e": "He rolled in the sand.", "k": "그는 모래에서 굴렀습니다."}, {"e": "Even now, every rhinoceros is angry and has wrinkled skin.", "k": "지금도 모든 코뿔소는 화가 나있고 주름진 가죽을 가지고 있습니다."}, {"e": "The man put cake crumbs inside the skin."}, {"e": "He punched and pulled the skin."}, {"e": "The rhinoceros finished swimming and put on his skin again."}, {"e": "He lives on a different beach now."}, {"e": "He took off his skin."}, {"e": "Why did it tickle?"}], "passage": ["One month later, the weather was very hot. “I want to go swimming today,” said the rhinoceros. He took off his skin. Then he hung it on a tree. The rhinoceros didn’t see the man. He was hiding behind the tree. The man stole the rhinoceros’s skin. What luck! The man now had the rhinoceros’s skin! “I will teach that rhinoceros,” he said. “I have a plan.” The man put cake crumbs inside the skin. He punched and pulled the skin. Soon the skin was wrinkled. Then the man hung the skin on the tree again.", "The rhinoceros finished swimming and put on his skin again. Why did it tickle? He scratched his skin. It tickled more! He rolled in the sand. It tickled even more! The rhinoceros couldn’t see the cake crumbs in his skin. The animal was tired and angry. So he went home. Even now, every rhinoceros is angry and has wrinkled skin. And the man? He lives on a different beach now. There are no rhinoceroses there!"], "qa": [["What was the weather like one month later?", "It was very hot."], ["What did the rhinoceros do before swimming?", "He took off his skin."], ["What did the man do?", "He stole the rhinoceros’s skin."], ["What will the man do?", "He will teach that rhinoceros a lesson."], ["What did the man put inside the skin?", "He put cake crumbs inside."], ["What did the skin soon look like?", "It looked wrinkled."], ["After swimming, what did the rhinoceros do?", "He put on his skin."], ["How did his skin feel?", "It tickled."], ["What is every rhinoceros like now?", "They are angry and have wrinkled skin."], ["Where does the man live?", "On a different beach with no rhinoceroses"]], "ox": [["The rhinoceros took off his skin to go swimming.", true], ["The man put sand inside the skin.", false], ["The skin tickled when the rhinoceros put it on.", true], ["The rhinoceros saw the crumbs in his skin.", false], ["Every rhinoceros has wrinkled skin now.", true]]}, "10": {"title": "King Frost", "vocab": [{"w": "everything", "k": "모든 것", "d": "all things", "s": [["Olga got everything she wanted.", "everything"]]}, {"w": "rude", "k": "예의 없는", "d": "not polite", "s": [["Olga was rude and spoiled.", "rude"]]}, {"w": "spoiled", "k": "버릇없는, 제멋대로 하는", "d": "always wanting your own way", "s": [["Olga was rude and spoiled.", "spoiled"]]}, {"w": "polite", "k": "예의 바른", "d": "speaking and acting nicely to others", "s": [["Eva was polite and kind.", "polite"]]}, {"w": "kind", "k": "친절한", "d": "nice and helpful to others", "s": [["Eva was polite and kind.", "kind"]]}, {"w": "forest", "k": "숲", "d": "a large area with many trees", "s": [["So Eva’s father took her out near the forest.", "forest"], ["I got lost in the forest.", "forest"], ["Send her out into the forest.", "forest"]]}, {"w": "freezing", "k": "꽁꽁 얼게 추운", "d": "very, very cold", "s": [["It’s freezing!", "freezing"]]}, {"w": "beg", "k": "빌다", "d": "to ask for something in a very strong way", "s": [["Eva’s father begged his wife.", "begged"]]}, {"w": "near", "k": "–에서 가까이", "d": "not far from", "s": [["So Eva’s father took her out near the forest.", "near"]]}, {"w": "chilly", "k": "추운", "d": "a little cold", "s": [["Aren’t you chilly?", "chilly"], ["It was too chilly to go swimming.", "chilly"]]}], "sentences": [{"e": "Olga was rude and spoiled.", "k": "Olga는 예의 없고 버릇없었습니다."}, {"e": "Eva was polite and kind.", "k": "Eva는 예의 바르고 친절했습니다."}, {"e": "Eva’s stepmother did not like her.", "k": "Eva의 새어머니는 그녀를 좋아하지 않았습니다."}, {"e": "The stepmother did not change her mind.", "k": "새어머니는 생각을 바꾸지 않았습니다."}, {"e": "Eva’s father begged his wife."}, {"e": "So Eva’s father took her out near the forest."}, {"e": "But she did not want the king to feel bad."}, {"e": "Little girl, your lips are blue."}, {"e": "Send her out into the forest."}, {"e": "Aren’t you chilly?"}], "passage": ["Once upon a time, a poor man had a daughter, Eva, and a stepdaughter, Olga. Olga got everything she wanted. Eva did not. Olga was rude and spoiled. Eva was polite and kind. Eva’s stepmother did not like her. “Send Eva away!” she said. “Send her out into the forest.” “No!” said Eva’s father. “I don’t want her to go. It’s freezing!” “Put her outside in the cold. I don’t want to see her face.” Eva’s father begged his wife, “Please, no!” The stepmother did not change her mind. So Eva’s father took her out near the forest. “Don’t’ cry, Father,” Eva said. “I will go.”", "Eva walked into the forest. She saw a tall man. “Do you know who I am?” the man said. “I am King Frost!” “Hello, Your Majesty!” said Eva. “Little girl, are you cold?” asked King Frost. “Oh no, King Frost. I am fine,” said Eva. She was very cold. But she did not want the king to feel bad. “Little girl, your lips are blue. Aren’t you chilly?” “Oh no, King Frost. I am fine.” King Frost liked Eva. She was polite!"], "qa": [["Who was Eva?", "A poor man’s daughter"], ["Who was Olga?", "A poor man’s stepdaughter"], ["What was Olga like?", "She was rude and spoiled."], ["What was Eva like?", "She was polite and kind."], ["What did Eva’s stepmother want?", "To send Eva away into the forest"], ["Why did Eva’s father not want her to go?", "It’s freezing."], ["Did the stepmother change her mind?", "No, she didn’t."], ["Who did Eva see in the forest?", "A tall man"], ["Who was the man?", "King Frost"], ["What did King Frost ask Eva?", "He asked if she was cold."], ["Why did Eva say she was not cold?", "She did not want the king to feel bad."], ["What color were Eva’s lips?", "They were blue."], ["Why did King Frost like Eva?", "She was polite."]], "ox": [["Olga was rude and spoiled.", true], ["Eva’s stepmother liked her very much.", false], ["Eva’s father took her out near the forest.", true], ["Eva told King Frost she was very cold.", false], ["King Frost liked Eva because she was polite.", true]]}, "11": {"title": "King Frost", "vocab": [{"w": "wrap", "k": "(감)싸다", "d": "to cover something with cloth or paper", "s": [["King Frost wrapped Eva in blankets and a fur robe.", "wrapped"]]}, {"w": "blanket", "k": "담요", "d": "a warm cover you use on a bed", "s": [["King Frost wrapped Eva in blankets and a fur robe.", "blankets"]]}, {"w": "robe", "k": "가운", "d": "a long, loose piece of clothing", "s": [["King Frost wrapped Eva in blankets and a fur robe.", "robe"], ["And there were no gorgeous robes for her.", "robes"], ["Bring back her jewels and robes as well!", "robes"]]}, {"w": "jewel", "k": "보석", "d": "a beautiful, expensive stone", "s": [["He gave her jewels!", "jewels"], ["Bring back her jewels and robes as well!", "jewels"]]}, {"w": "sled", "k": "썰매", "d": "a thing you ride on snow", "s": [["Then he put her in his sled.", "sled"]]}, {"w": "blizzard", "k": "눈보라", "d": "a big snowstorm with strong wind", "s": [["A blizzard began!", "blizzard"], ["Last winter we had a lot of blizzards.", "blizzards"]]}, {"w": "begin", "k": "시작하다", "d": "to start", "s": [["A blizzard began!", "began"]]}, {"w": "gorgeous", "k": "아주 멋진", "d": "very beautiful", "s": [["And there were no gorgeous robes for her.", "gorgeous"]]}, {"w": "bring", "k": "데려오다, 가져오다", "d": "to take someone or something with you to a place", "s": [["The stepmother sent her husband to bring Olga home.", "bring"], ["Bring back her jewels and robes as well!", "Bring"]]}, {"w": "icicle", "k": "고드름", "d": "a long, pointed piece of ice", "s": [["But all he found was an icicle.", "icicle"], ["Icicles hang from tree branches in winter.", "Icicles"]]}], "sentences": [{"e": "King Frost took Eva back to her home.", "k": "Frost 왕은 Eva를 집으로 데려갔습니다."}, {"e": "But the stepmother did not listen.", "k": "그러나 새어머니는 듣지 않았습니다."}, {"e": "And there were no gorgeous robes for her.", "k": "그리고 그녀를 위한 아주 멋진 가운도 없었습니다."}, {"e": "But all he found was an icicle.", "k": "그러나 그가 찾은 것은 고드름뿐이었습니다."}, {"e": "King Frost wrapped Eva in blankets and a fur robe."}, {"e": "Of course I am cold."}, {"e": "Instead, the king made Olga colder and colder."}, {"e": "Bring back her jewels and robes as well!"}, {"e": "He gave her jewels!"}, {"e": "A blizzard began!"}], "passage": ["wrapped Eva in blankets and a fur robe. He gave her jewels! Then he put her in his sled. King Frost took Eva back to her home. Her father was happy to see her! “I’m sorry I left you,” he said. The stepmother thought about this over and over again. “Take Olga out,” said the stepmother, at last. “Leave her in the forest. She can get robes and jewels, too!” “No, it’s freezing!” said the father. But the stepmother did not listen. So the father took Olga out into the forest.Olga started walking in the forest. A blizzard began!", "saw Olga. “I am King Frost!” he said. “Little girl, are you chilly?” he asked. “What do you think? You’re making it snow!” snarled Olga. The king was mad. “Do you say you are cold?” “You fool! Of course I am cold,” said Olga. King Frost had no jewels for Olga. And there were no gorgeous robes for her. She was too rude. Instead, the king made Olga colder and colder. The stepmother sent her husband to bring Olga home. “Bring back her jewels and robes as well!” she said. But all he found was an icicle."], "qa": [["What did King Frost give Eva?", "He gave her jewels."], ["Where did he take Eva?", "He took her back home."], ["Who was happy that Eva was back home?", "Her father"], ["Why did the stepmother want to leave Olga in the forest?", "So she can get robes and jewels like Eva."], ["Why didn’t the father want to take Olga out?", "It was freezing."], ["What happened while Olga was in the forest?", "A blizzard began!"], ["What did King Frost ask Olga?", "He asked if she was chilly."], ["Was Olga kind when she talked to the king?", "No, she was rude."], ["What did King Frost do to Olga?", "He made her colder and colder."], ["What did the stepmother want her husband to bring back?", "Olga, her jewels, and robes"], ["What happened to Olga?", "She became an icicle."]], "ox": [["King Frost gave Eva jewels.", true], ["The stepmother sent Olga into the forest.", true], ["Olga was polite to King Frost.", false], ["King Frost gave Olga gorgeous robes.", false], ["The father found only an icicle.", true]]}, "12": {"title": "The Golden Goose", "vocab": [{"w": "son", "k": "아들", "d": "a person’s boy child", "s": [["There was a man with three sons.", "sons"], ["We have two sons and a daughter.", "sons"]]}, {"w": "share", "k": "나누다", "d": "to give part of what you have to others", "s": [["I will not share.", "share"]]}, {"w": "badly", "k": "심하게, 몹시", "d": "in a very serious way", "s": [["He began to cut down a tree, but he cut his  arm badly.", "badly"], ["He began to cut down a tree, but he cut his leg badly.", "badly"]]}, {"w": "burnt", "k": "(불에) 탄", "d": "black and damaged by fire", "s": [["His mother gave him a burnt cake and old beer.", "burnt"]]}, {"w": "help yourself", "k": "마음껏 드세요", "d": "take as much as you want", "s": [["Help yourself.", "Help yourself"], ["Help yourself to some dessert.", "Help yourself"]]}, {"w": "fine", "k": "괜찮은, 좋은", "d": "very good", "s": [["When he opened his bag, he found fine  cake and wine.", "fine"], ["When he opened his bag, he found fine cake and wine.", "fine"]]}, {"w": "goose", "k": "거위", "d": "a large bird like a duck", "s": [["Inside was a goose with golden feathers.", "goose"], ["But her hand stuck to the goose.", "goose"]]}, {"w": "feather", "k": "깃털", "d": "one of the soft things that cover a bird", "s": [["Inside was a goose with golden feathers.", "feathers"], ["The innkeeper’s daughters wanted a golden feather.", "feather"], ["The eldest daughter tried to take a feather.", "feather"]]}, {"w": "stick", "k": "붙다", "d": "to become joined to something and not come off", "s": [["But her hand stuck to the goose.", "stuck"], ["They were stuck all night.", "stuck"], ["He tried to pull the youngest girl away, but he got stuck.", "stuck"]]}, {"w": "all night", "k": "밤새도록", "d": "from evening to morning", "s": [["They were stuck all night.", "all night"]]}], "sentences": [{"e": "In the forest, he met an old man, who asked for food and drink.", "k": "숲에서 그는 음식과 마실 것을 부탁하는 노인을 만났습니다."}, {"e": "Inside was a goose with golden feathers.", "k": "안에는 황금빛 깃털을 가진 거위가 있었습니다."}, {"e": "The eldest daughter tried to take a feather.", "k": "첫째 딸은 깃털을 가져가려고 했습니다."}, {"e": "He tried to pull the youngest girl away, but he got stuck.", "k": "그는 막내 소녀를 떼어 보려고 했지만 그도 붙어버렸습니다."}, {"e": "He began to cut down a tree, but he cut his leg badly."}, {"e": "When he opened his bag, he found fine cake and wine."}, {"e": "The innkeeper’s daughters wanted a golden feather."}, {"e": "The three girls ran behind him."}, {"e": "Help yourself."}, {"e": "They were stuck all night."}], "passage": ["There was a man with three sons. The eldest son went to cut wood. His mother gave him some cake and wine. In the forest, he met an old man, who asked for food and drink. “I will not share,” said the son. He began to cut down a tree, but he cut his arm badly. The second son went to cut wood. His mother gave him some cake and wine. In the forest, he met the old man, who again asked for food and drink. “I will not share,” said the son. He began to cut down a tree, but he cut his leg badly. The youngest son, Dummling, went to cut wood. His mother gave him a burnt cake and old beer. In the forest, he met the old man. The old man asked for food and drink. “Help yourself,” said Dummling. When he opened his bag, he found fine cake and wine.", "“You are a good man,” said the old man. “Cut down that old tree.” Dummling cut down the tree. Inside was a goose with golden feathers. Dummling went to an inn. The innkeeper’s daughters wanted a golden feather. The eldest daughter tried to take a feather. But her hand stuck to the goose. The second daughter tried to get a feather. But her hand stuck to her sister. The third daughter came to get a feather. She got stuck, too. They were stuck all night. The next morning, Dummling left the inn. The three girls ran behind him. In a field, they met a priest. He tried to pull the youngest girl away, but he got stuck. Two farm workers saw them. They tried to pull the priest away, but they got stuck."], "qa": [["Who went to cut wood?", "The eldest son"], ["What did the old man ask for?", "Some food and drink"], ["What happened to the eldest son’s arm?", "He cut his arm badly."], ["Who went into the forest next?", "The second son"], ["Did he share with the old man?", "No, he didn’t."], ["What happened to his leg?", "He cut his leg badly."], ["Who went to cut wood next?", "The youngest son, Dummling"], ["Did Dummling share with the old man?", "Yes, he did."], ["What did the old man tell Dummling to do?", "Cut down an old tree"], ["What was inside the tree?", "A goose with golden feathers"], ["Who tried to take a feather from the goose?", "The innkeeper’s three daughters"], ["What happened when they tried to take a feather?", "Their hands got stuck."], ["Who did they meet in a field?", "A priest"], ["What did the priest try to do?", "He tried to pull the girl away."], ["Why did the farmers get stuck?", "They tried to pull the priest away."]], "ox": [["The man had three sons.", true], ["The eldest son shared his food with the old man.", false], ["Dummling’s mother gave him a burnt cake.", true], ["There was a goose with golden feathers inside the tree.", true], ["The priest pulled the girl away easily.", false]]}, "13": {"title": "The Golden Goose", "vocab": [{"w": "anyone", "k": "누구, 누구나", "d": "any person", "s": [["He said anyone who could make the princess laugh  could marry her.", "anyone"], ["He said anyone who could make the princess laugh could marry her.", "anyone"]]}, {"w": "thirsty", "k": "목이 마른", "d": "wanting to drink something", "s": [["I am so thirsty, but no drink is enough.", "thirsty"], ["They were hungry and thirsty.", "thirsty"]]}, {"w": "enough", "k": "충분한", "d": "as much as you need", "s": [["I am so thirsty, but no drink is enough.", "enough"]]}, {"w": "until", "k": "–까지", "d": "up to the time that", "s": [["The man drank and drank until the wine was gone.", "until"]]}, {"w": "strap", "k": "끈", "d": "a long, thin band of cloth or leather", "s": [["He found a man putting a strap around his body.", "strap"]]}, {"w": "palace", "k": "궁전", "d": "a big house where a king or queen lives", "s": [["Dummling took him to the king’s palace.", "palace"], ["The king and his family live in the palace.", "palace"]]}, {"w": "sail", "k": "항해하다", "d": "to travel on water in a ship", "s": [["Bring me a ship that can sail on land and on water.", "sail"]]}, {"w": "promise", "k": "약속하다", "d": "to say you will surely do something", "s": [["“Then you can marry the princess,” promised the king.", "promised"]]}, {"w": "become", "k": "–이 되다", "d": "to start to be something", "s": [["Dummling became a rich man and lived happily  with his wife.", "became"]]}, {"w": "happily", "k": "행복하게", "d": "in a happy way", "s": [["Dummling became a rich man and lived happily  with his wife.", "happily"]]}], "sentences": [{"e": "The king had a daughter who would not laugh.", "k": "왕에게는 웃지 않는 딸이 있었습니다."}, {"e": "He said anyone who could make the princess laugh could marry her.", "k": "그는 공주를 웃게 만들 수 있는 사람은 누구든지 그녀와 결혼할 수 있다고 말했습니다."}, {"e": "Dummling went into the forest and found the old man.", "k": "Dummling은 숲으로 들어가 노인을 찾았습니다."}, {"e": "The king had to let Dummling marry his daughter.", "k": "왕은 Dummling이 그의 딸과 결혼하도록 해야 했습니다."}, {"e": "When the princess saw Dummling, she laughed and laughed."}, {"e": "He found a man putting a strap around his body."}, {"e": "Dummling took him to the king’s palace."}, {"e": "You gave me food and drink, so I will give you the ship."}, {"e": "I am so thirsty, but no drink is enough."}, {"e": "Bring me a ship that can sail on land and on water."}], "passage": ["Soon, they came to a city. The king had a daughter who would not laugh. He said anyone who could make the princess laugh could marry her. When the princess saw Dummling, she laughed and laughed. But the king didn’t want Dummling to marry his daughter. “Bring me a man who can drink all my wine,” said the king to Dummling. Dummling went into the forest. He found a sad man. “Why are you sad?” asked Dummling. “I am so thirsty, but no drink is enough,” said the man. “I can help you,” said Dummling. He took the man to the king’s wine. The man drank and drank until the wine was gone.", "“Bring me a man who can eat a mountain of bread,” said the king to Dummling. Dummling went into the forest. He found a man putting a strap around his body. “I am so hungry, but no food is enough,” said the man. “I can help you,” said Dummling. Dummling took him to the king’s palace. There was a big mountain of bread. The man ate all the bread. “Bring me a ship that can sail on land and on water. Then you can marry the princess,” promised the king. Dummling went into the forest and found the old man. “You gave me food and drink, so I will give you the ship,” said the old man. The king had to let Dummling marry his daughter. Dummling became a rich man and lived happily with his wife."], "qa": [["What would the princess not do?", "She would not laugh."], ["Who could marry the princess?", "Anyone who could make her laugh"], ["Who made the princess laugh?", "Dummling"], ["Who did Dummling find in the forest?", "He found a sad man."], ["Why was the man sad?", "He was so thirsty."], ["What did the thirsty man do?", "He drank all the king’s wine."], ["What did the king want Dummling to bring him?", "A man who can eat a mountain of bread"], ["What was the man doing in the forest?", "Putting a strap around his body"], ["What was the man’s problem?", "He was very hungry."], ["What did the man do at the king’s palace?", "He ate the mountain of bread."], ["What did the king ask Dummling to bring him?", "A ship that can sail on land and on water"], ["Who gave Dummling the ship?", "The old man he helped"], ["What happened after Dummling married the princess?", "He became a rich man and was happy."]], "ox": [["The princess laughed when she saw Dummling.", true], ["The thirsty man could not drink all the wine.", false], ["A man ate a mountain of bread.", true], ["The old man gave Dummling a ship.", true], ["Dummling did not marry the princess.", false]]}, "15": {"title": "Momotaro", "vocab": [{"w": "demon", "k": "악마", "d": "a bad monster in stories", "s": [["Demons stole their money.", "Demons"]]}, {"w": "peach", "k": "복숭아", "d": "a soft, sweet fruit with a big seed", "s": [["After dinner, the woman cut the peach.", "peach"], ["I planted a peach tree in my yard.", "peach"], ["She saw a fresh peach in the water.", "peach"]]}, {"w": "take care of", "k": "–을 돌보다", "d": "to look after someone", "s": [["He has to take care of his sick mother.", "take care of"]]}, {"w": "grow up", "k": "자라다", "d": "to become an adult", "s": [["Momotaro grew up strong and smart.", "grew up"]]}, {"w": "strong", "k": "강한", "d": "having a lot of power", "s": [["Momotaro grew up strong and smart.", "strong"]]}, {"w": "smart", "k": "똑똑한", "d": "good at thinking and learning", "s": [["Momotaro grew up strong and smart.", "smart"]]}, {"w": "brave", "k": "용감한", "d": "not afraid of danger", "s": [["He was also very brave.", "brave"]]}, {"w": "strength", "k": "힘", "d": "the power of the body", "s": [["They will give you strength.", "strength"]]}, {"w": "prepare", "k": "준비하다", "d": "to get ready", "s": [["Momotaro prepared to leave.", "prepared"]]}, {"w": "join", "k": "함께 하다", "d": "to go with someone and do something together", "s": [["I will join you.", "join"]]}], "sentences": [{"e": "There was a baby inside!"}, {"e": "Momotaro grew up strong and smart."}, {"e": "He was also very brave."}, {"e": "I will bring back the people’s money."}, {"e": "She saw a fresh peach in the water."}, {"e": "They will give you strength."}], "passage": ["Once there was an old couple. They lived in a small town. The people in the town were good but poor. Demons stole their money. Life was hard. One day, the old woman went to the river to wash clothes. She saw a fresh peach in the water. She picked it up. “We can have this peach after dinner,” she said. After dinner, the woman cut the peach. There was a baby inside! “A baby!” cried the couple. “He will be our child,” said the old woman. “We will name him Momotaro,” said the old man. “He came from a peach. He is our little peach boy.” The old couple loved their son. They took very good care of him.", "grew up strong and smart. He was also very brave. “The demons always take our money,” said Momotaro one day. “I will stop them. I will bring back the money.” The old couple were worried. But they couldn’t stop him. “I will make dumplings for you,” said the old woman. “Take them with you. They will give you strength.” Momotaro prepared to leave. The old couple helped him. Momotaro left his house. He was going to find the demons. He started walking down the road. A monkey called out to him. “Where are you going?” asked the monkey. “I am going to find the demons. I will bring back the people’s money,” said Momotaro. “Give me a dumpling. I will join you,” said the monkey."], "qa": [["Why were the people in the town poor?", "Demons stole their money."], ["What did the woman see in the river?", "She saw a fresh peach."], ["What did she want to do with the peach?", "She wanted to eat it after dinner."], ["What was inside the peach?", "A baby"], ["What did they name the baby?", "They named him Momotaro."], ["Why did the name him Momotaro?", "Because he came from a peach"], ["What was Momotaro like?", "He was strong, smart, and very brave."], ["What will Momotaro do to the demons?", "He will stop them and bring back the money."], ["What food will the old woman make for him?", "She will make dumplings."], ["Why will she give him dumplings?", "The dumplings will give Momotaro strength."], ["Who called out to Momotaro on the road?", "A monkey"], ["What did the monkey want to know?", "He wanted to know where Momotaro was going."], ["What did the monkey want Momotaro to give him?", "A dumpling"], ["Where will the monkey go?", "He will go with Momotaro."]], "ox": [["Demons stole the town’s money.", true], ["The old woman found a peach in the river.", true], ["There was a cat inside the peach.", false], ["Momotaro grew up strong and smart.", true], ["The old woman made cookies for Momotaro.", false]]}, "16": {"title": "Momotaro", "vocab": [{"w": "continue", "k": "계속하다", "d": "to keep doing something", "s": [["Momotaro continued his journey with his new friend.", "continued"]]}, {"w": "journey", "k": "여행(여정)", "d": "a long trip", "s": [["Momotaro continued his journey with his new friend.", "journey"]]}, {"w": "through", "k": "–을 지나서", "d": "from one side to the other side of", "s": [["We will go through the gate.", "through"]]}, {"w": "surprise", "k": "놀라게 하다", "d": "to do something someone does not expect", "s": [["The four friends surprised the demons.", "surprised"]]}, {"w": "leader", "k": "대장, 리더", "d": "the person who leads a group", "s": [["Soon only the leader of the demons was left.", "leader"]]}, {"w": "frightening", "k": "무서운", "d": "making you feel afraid", "s": [["He was frightening.", "frightening"]]}, {"w": "finally", "k": "마침내", "d": "at last", "s": [["Finally, Ankadoji had to give up.", "Finally"], ["Two hours later, the train finally arrived.", "finally"]]}, {"w": "give up", "k": "포기하다", "d": "to stop trying", "s": [["Finally, Ankadoji had to give up.", "give up"], ["Keep trying! Don’t give up.", "give up"]]}, {"w": "hero", "k": "영웅", "d": "a brave person who does great things", "s": [["Momotaro was a hero.", "hero"]]}, {"w": "return", "k": "돌아오다(가다)", "d": "to come or go back", "s": [["He returned home.", "returned"]]}], "sentences": [{"e": "Momotaro continued his journey with his new friend.", "k": "Momotaro는 새로운 친구와 여행을 계속했습니다."}, {"e": "The four friends found the demons’ castle.", "k": "네 친구는 악마의 성을 찾았습니다."}, {"e": "Finally, Ankadoji had to give up.", "k": "마침내 Ankadoji는 포기해야 했습니다."}, {"e": "Momotaro was a hero.", "k": "Momotaro는 영웅이었습니다."}, {"e": "Are you going to stop the demons?"}, {"e": "We will go through the gate."}, {"e": "The four friends surprised the demons."}, {"e": "They fought for a very long time."}, {"e": "He was frightening."}, {"e": "How dare you come here?"}], "passage": ["continued his journey with his new friend. They met a dog along the road. “I smell dumplings,” said the dog. He sniffed Momotaro’s bag. “Give me a dumpling. I will join you.” A bird landed on the road. “Are you going to stop the demons?” the bird asked. “Yes, I am,” said Momotaro. “Give me a dumpling. I will join you,” said the bird. The four friends found the demons’ castle. There was a big wall. It went all around the castle. “I will fly over the wall,” said the bird. “I will climb over the wall,” said the monkey.", "“We will go through the gate,” said Momotaro to the dog. The four friends surprised the demons. They fought the demons bravely. They were strong. Soon only the leader of the demons was left. His name was Ankadoji. He was frightening. He spoke with a loud voice. “How dare you come here?” shouted Ankadoji. “This money is all mine. I took it.” “It is not your money. You stole it. I will take it back,” said Momotaro. Ankadoji ran at Momotaro. They fought for a very long time. Finally, Ankadoji had to give up. Momotaro had won! “Take the money,” the demon said. “I won’t steal from the people again.” Momotaro was a hero. He returned home. He brought back the money. Everyone was happy to see him."], "qa": [["Who did Momotaro and the monkey meet on the road?", "They met a dog."], ["What did the dog want from Momotaro?", "He wanted a dumpling."], ["What did the bird want to know?", "If they were going to stop the demons."], ["What does the bird want?", "The bird wants a dumping, and to join them."], ["What was all around the castle?", "A big wall"], ["How will Momotaro and the dog get to the castle?", "They will go through the gate."], ["How did the four friends fight?", "They fought bravely."], ["What was the leader of the demons like?", "He was frightening and spoke with a loud voice."], ["Why does Ankadoji think the money is his?", "Because he took it"], ["What did Ankadoji and Momotaro do?", "They fought for a long time."], ["Who won the fight?", "Momotaro won!"], ["What will Ankadoji not do again?", "He will not steal from the people."], ["What was Momotaro?", "He was a hero."], ["What did he bring back?", "Momotaro brought back the money."]], "ox": [["Momotaro met a dog and a bird on the road.", true], ["The monkey flew over the wall.", false], ["Ankadoji was the leader of the demons.", true], ["Momotaro gave up in the end.", false], ["Momotaro brought back the money.", true]]}, "17": {"title": "An Uncomfortable Bed", "vocab": [{"w": "joke", "k": "농담, 장난", "d": "something you say or do to make people laugh", "s": [["My friends like to play jokes.", "jokes"], ["I tried to remember all the jokes my friends had  played on me.", "jokes"], ["I tried to remember all the old jokes my friends had played on me.", "jokes"]]}, {"w": "arrive", "k": "도착하다", "d": "to get to a place", "s": [["When I arrived, they welcomed me.", "arrived"]]}, {"w": "welcome", "k": "환영하다", "d": "to greet someone in a happy way", "s": [["When I arrived, they welcomed me.", "welcomed"]]}, {"w": "suspicious", "k": "의심스러운", "d": "feeling that something is wrong", "s": [["I felt suspicious.", "suspicious"]]}, {"w": "sure", "k": "확신하는", "d": "certain", "s": [["I was sure they had planned a trick.", "sure"]]}, {"w": "whisper", "k": "속삭이다", "d": "to speak very quietly", "s": [["Then I heard laughing and whispering outside my  room.", "whispering"], ["You don’t have to whisper. No one can hear us.", "whisper"]]}, {"w": "spy", "k": "감시하다", "d": "to watch someone secretly", "s": [["My friends were spying on me!", "spying"]]}, {"w": "check", "k": "살피다, 확인하다", "d": "to look at something carefully", "s": [["I checked under the furniture.", "checked"]]}, {"w": "trust", "k": "믿다", "d": "to believe someone is good and honest", "s": [["I did not trust the bed.", "trust"]]}, {"w": "remember", "k": "기억하다", "d": "to keep something in your mind", "s": [["I tried to remember all the jokes my friends had  played on me.", "remember"], ["I can’t remember her name.", "remember"], ["I tried to remember all the old jokes my friends had played on me.", "remember"]]}], "sentences": [{"e": "When I arrived, they welcomed me.", "k": "내가 도착했을 때 그들은 나를 환영했습니다."}, {"e": "All evening, I watched my friends carefully.", "k": "저녁 내내 나는 친구들을 주의 깊게 봤습니다."}, {"e": "I checked under the furniture.", "k": "나는 가구 밑을 확인했습니다."}, {"e": "I put a chair in front of the window.", "k": "나는 창문 앞에 의자를 놓았습니다."}, {"e": "I was sure they had planned a trick."}, {"e": "My friends were spying on me!"}, {"e": "My candle may go out and leave me in the dark."}, {"e": "I tried to remember all the old jokes my friends had played on me."}, {"e": "My friends like to play jokes."}, {"e": "I did not trust the bed."}], "passage": ["My friends like to play jokes. They play them often. I like to joke around as well. Last fall, I went to stay with some friends. When I arrived, they welcomed me. I felt suspicious. I was sure they had planned a trick. During dinner, we had a great time. My friends all laughed a lot. I thought, “They are laughing so much because they are planning a joke on me!” All evening, I watched my friends carefully. Finally, it was time for bed. I said good night and went to my room. I closed my bedroom door. Then I heard laughing and whispering outside my room. My friends were spying on me! I checked under the furniture. But I found nothing.", "I heard people moving about outside my door. “They are looking through the keyhole!” I thought. I looked through the keyhole but saw nothing. It was getting late. “My candle may go out and leave me in the dark,” I said. So I lit five more candles. After that, I went over to the window. I closed the shutters and then drew the curtains. I put a chair in front of the window. I was sure nothing could come in. Then I sat down in an armchair. I was tired, but I did not get into the bed. I did not trust the bed. I looked again at the curtains. They seemed to be secure. All the same, I was sure there was danger. Perhaps my friends planned to drop cold water on me from overhead. I tried to remember all the old jokes my friends had played on me. I was smart! They would not trick me! Oh, no, certainly not!"], "qa": [["What do the man’s friends like to do?", "They like to play jokes."], ["Why did the man feel suspicious?", "He thought his friends planned a trick."], ["Why did the man think his friends were laughing so much?", "He thought his friends were planning a joke on him."], ["What did the man hear outside his room?", "He heard laughing and whispering."], ["What did he think his friends were doing?", "He thought they were spying on him."], ["Why did the man think his friends were looking through the keyhole?", "He heard people moving outside his door."], ["Were his friends spying on him or looking through the keyhole?", "No, they were not!"], ["Why did the man light 5 more candles?", "So if his candle went out, he would not be in the dark."], ["What did he do to the window? (3 things)", "He closed the shutters, drew the curtains, and put a chair in front of the window."], ["Why did he not get into the bed?", "He did not trust the bed."], ["What did the man think his friends planned to do?", "He thought they planned to drop cold water on him."], ["Does the man think he will be tricked?", "No, he doesn’t."]], "ox": [["The writer’s friends like to play jokes.", true], ["The writer trusted his friends that night.", false], ["The writer lit five more candles.", true], ["The writer slept in the bed.", false], ["The writer put a chair in front of the window.", true]]}, "18": {"title": "An Uncomfortable Bed", "vocab": [{"w": "enter", "k": "들어가다", "d": "to go into a place", "s": [["No one could enter the room without waking me!", "enter"]]}, {"w": "liquid", "k": "액체", "d": "something like water that can flow", "s": [["A hot liquid poured onto my face,  neck, and chest!", "liquid"], ["Air is not a liquid.", "liquid"], ["A hot liquid poured onto my face, neck, and chest!", "liquid"]]}, {"w": "pain", "k": "아픔", "d": "the feeling when a part of your body hurts", "s": [["I cried out in pain.", "pain"]]}, {"w": "beard", "k": "수염", "d": "hair that grows on a man’s face", "s": [["I felt a face, a nose, and a beard!", "beard"]]}, {"w": "fear", "k": "두려움", "d": "the feeling of being afraid", "s": [["I shouted in fear and ran from my room.", "fear"]]}, {"w": "trip over", "k": "–에 발이 걸려 넘어지다", "d": "to hit your foot on something and fall", "s": [["He had tripped over me sleeping in the middle of  the floor.", "tripped over"], ["He had tripped over me sleeping in the middle of the floor.", "tripped over"]]}, {"w": "spill", "k": "흘리다", "d": "to let a liquid fall out by accident", "s": [["Then he had fallen and spilled the tea over my face!", "spilled"]]}, {"w": "thief", "k": "도둑", "d": "a person who steals things", "s": [["Thinking I was a thief, he then punched me!", "thief"], ["The policeman caught the thief.", "thief"]]}, {"w": "avoid", "k": "피하다", "d": "to stay away from something", "s": [["I had tried so hard to avoid any tricks.", "avoid"]]}, {"w": "instead", "k": "대신에", "d": "in place of something else", "s": [["But I made myself a joke instead.", "instead"]]}], "sentences": [{"e": "No one could enter the room without waking me!", "k": "아무도 나를 깨우지 않고 방에 들어갈 수 없었습니다!"}, {"e": "When everything seemed quiet, I fell asleep.", "k": "모든 것이 조용해졌을 때 나는 잠이 들었습니다."}, {"e": "Then he had fallen and spilled the tea over my face!", "k": "그런 다음 그는 넘어져 내 얼굴에 차를 흘렸습니다!"}, {"e": "Thinking I was a thief, he then punched me!", "k": "내가 도둑이라고 생각해서 그는 나를 주먹으로 쳤습니다!"}, {"e": "Now I was safe from tricks!"}, {"e": "A hot liquid poured onto my face, neck, and chest!"}, {"e": "He had come to bring me a cup of morning tea."}, {"e": "He had tripped over me sleeping in the middle of the floor."}, {"e": "I felt a face, a nose, and a beard!"}, {"e": "I had tried so hard to avoid any tricks."}], "passage": ["I had a good idea. I pulled the mattress and sheets off the bed. Then I pulled them to the middle of the room, facing the door. I made up my bed there. No one could enter the room without waking me! Now I was safe from tricks! With this, I put out all the candles and got into bed. For another hour, I was still awake. When everything seemed quiet, I fell asleep. I must have been in a deep sleep for a long time. Suddenly, I was woken by something falling on me. A hot liquid poured onto my face, neck, and chest! I cried out in pain. Then there was a noise of plates and cups falling to the ground. What was this trick? Had my friends played a joke on me after all? I put out my hand. I felt a face, a nose, and a beard! Then I felt a hand punch me! I shouted in fear and ran from my room.", "My friends came to see what the noise was. We looked into my room together. What did we see? A poor servant! He had come to bring me a cup of morning tea. He had tripped over me sleeping in the middle of the floor. Then he had fallen and spilled the tea over my face! Thinking I was a thief, he then punched me! I had tried so hard to avoid any tricks. I had closed the shutters tightly. I had slept in the middle of the room. But I made myself a joke instead. Ah! How my friends all laughed that day!"], "qa": [["What was the man’s good idea?", "It was to put the mattress in the middle of the room facing the door."], ["Why did he think it was a good idea?", "Because no one could go into the room without waking him up"], ["When did the man go to sleep?", "When everything seemed quiet"], ["Why did the man wake up?", "A hot liquid poured onto him."], ["What noise did he hear?", "He heard plates and cups falling."], ["What did the man feel?", "He felt a face, a nose, and a beard."], ["What did the hand do?", "It punched him!"], ["Who was in the man’s room?", "A servant"], ["What happened when the servant brought the man tea?", "The servant tripped over the man and spilled the tea."], ["Why did the servant punch the man?", "He thought the man was a thief."], ["What did the man try do avoid?", "He tried to avoid any tricks."], ["What did the man do instead?", "He made himself a joke."]], "ox": [["The writer made his bed in the middle of the room.", true], ["Cold water fell on the writer’s face.", false], ["A servant brought a cup of morning tea.", true], ["The servant tripped over the writer.", true], ["The friends did not laugh at all.", false]]}, "21": {"title": "How Bear Lost His Tail", "vocab": [{"w": "tail", "k": "꼬리", "d": "the part at the back end of an animal", "s": [["Long ago, Bear had a tail.", "tail"], ["Bear talked a lot about his tail.", "tail"], ["He put his tail into the hole in the ice.", "tail"]]}, {"w": "proud", "k": "자랑스러워 하는", "d": "feeling happy about something you have or did", "s": [["He was proud of it.", "proud"]]}, {"w": "meet", "k": "만나다", "d": "to see and talk to someone", "s": [["Bear met Bird.", "met"]]}, {"w": "winter", "k": "겨울", "d": "the coldest season of the year", "s": [["One winter day, Fox had an idea.", "winter"], ["We go skiing every winter.", "winter"]]}, {"w": "lake", "k": "호수", "d": "a large area of water with land all around it", "s": [["He went to the lake.", "lake"]]}, {"w": "hole", "k": "구멍", "d": "an empty space in something", "s": [["He cut a hole in the ice.", "hole"], ["Fox put the fish next to the hole.", "hole"], ["Let’s make another hole for you.", "hole"]]}, {"w": "ice", "k": "얼음", "d": "frozen water", "s": [["He cut a hole in the ice.", "ice"], ["The ice is hard enough to skate on.", "ice"], ["He put his tail into the hole in the ice.", "ice"]]}, {"w": "next to", "k": "–바로 옆에", "d": "very close, at the side of", "s": [["Fox put the fish next to the hole.", "next to"]]}, {"w": "turn", "k": "몸을 돌리다", "d": "to move your body to face another way", "s": [["Fox turned.", "turned"]]}, {"w": "let’s", "k": "–합시다", "d": "a word you use to say “we should do this”", "s": [["Let’s make another hole for you.", "Let’s"]]}], "sentences": [{"e": "Long ago, Bear had a tail.", "k": "옛날에 곰에게는 꼬리가 있었습니다."}, {"e": "One winter day, Fox had an idea.", "k": "어느 겨울날 여우는 생각이 떠올랐습니다."}, {"e": "Fox put the fish next to the hole.", "k": "여우는 물고기를 구멍 바로 옆에 놓았습니다."}, {"e": "He put his tail into the hole in the ice.", "k": "그는 얼음 구멍에 꼬리를 넣었습니다."}, {"e": "Bear talked a lot about his tail."}, {"e": "Where did you get those fish?"}, {"e": "When they bite mine, I pull them up."}, {"e": "Let’s make another hole for you."}, {"e": "He was proud of it."}, {"e": "It’s long and brown!"}], "passage": ["Long ago, Bear had a tail. It was a very nice tail! He was proud of it. Bear met Bird. He said, “Look at my tail. It’s pretty!” Bear met Fox. He said, “Look at my tail. It’s long and brown!” Bear talked a lot about his tail. Fox and Bird did not like that. One winter day, Fox had an idea. He went to the lake. He cut a hole in the ice. He caught a lot of fish. Fox put the fish next to the hole. Then he waited. Bear came. Bear saw all the fish. He said, “Fox! Where did you get those fish?” Fox said, “I caught them.” Fox turned. He put his tail into the hole in the ice. Fox said, “Fish like tails. When they bite mine, I pull them up.” Bear looked at the hole. Then he looked at his tail. Bear asked, “Can I try?” “Ok,” said Fox. “But not here. Let’s make another hole for you.”"], "qa": [["What did Bear have long ago?", "He had a tail."], ["What was his tail like?", "It was very nice, pretty, long and brown."], ["What did Fox and Bird not like?", "They did not like that Bear talked a lot about his tail."], ["What did fox do at the lake?", "He cut a hole and caught a lot of fish."], ["Where did Fox put the fish?", "He put them next to the hole."], ["What did Bear want to know?", "He wanted to know where Fox got the fish."], ["Where did Fox put his tail?", "Into the hole in the ice"], ["What did Fox say fish like?", "He said they like tails."], ["How did Fox say he caught the fish?", "He said he put his tail into the hole and when the fish bit his tail, he pulled them up."], ["What does Bear want to do?", "He wants to try to catch fish with his tail."]], "ox": [["Bear was proud of his tail.", true], ["Fox and Bird liked Bear’s talk about his tail.", false], ["Fox cut a hole in the ice.", true], ["Fox caught a lot of fish.", true], ["Fox made a hole for Bear in the same place.", false]]}, "22": {"title": "How Bear Lost His Tail", "vocab": [{"w": "another", "k": "다른", "d": "one more or a different one", "s": [["Fox went to another part of the lake.", "another"]]}, {"w": "part", "k": "부분, 쪽", "d": "a piece of something", "s": [["Fox went to another part of the lake.", "part"]]}, {"w": "deep", "k": "깊은", "d": "going far down", "s": [["The water was not deep there.", "deep"], ["She dug a deep hole in the garden.", "deep"]]}, {"w": "wait", "k": "기다리다", "d": "to stay until something happens", "s": [["Now wait.", "wait"], ["I will wait behind those trees.", "wait"]]}, {"w": "move", "k": "움직이다", "d": "to change place", "s": [["Don’t move.", "move"], ["Bear did not move.", "move"]]}, {"w": "think", "k": "생각하다", "d": "to use your mind", "s": [["Don’t think.", "think"], ["Fish can hear you think.", "think"], ["He tried not to think.", "think"]]}, {"w": "watch", "k": "보다", "d": "to look at something for a time", "s": [["I will watch the hole.", "watch"], ["He is watching an old movie.", "watching"]]}, {"w": "bite", "k": "물다", "d": "to cut something with your teeth", "s": [["When a fish bites your tail, I will tell you.", "bites"]]}, {"w": "answer", "k": "대답하다", "d": "to say something back", "s": [["Bear did not answer.", "answer"]]}, {"w": "behind", "k": "–뒤에", "d": "at the back of", "s": [["I will wait behind those trees.", "behind"], ["Fox went behind the trees.", "behind"]]}], "sentences": [{"e": "Fox went to another part of the lake.", "k": "여우는 호수의 다른 쪽으로 갔습니다."}, {"e": "The water was not deep there.", "k": "그곳은 물이 깊지 않았습니다."}, {"e": "Fox went behind the trees.", "k": "여우는 나무 뒤로 갔습니다."}, {"e": "Then he ate his fish and went home.", "k": "그런 다음 그는 물고기를 먹고 집에 갔습니다."}, {"e": "Fish can hear you think."}, {"e": "I will watch the hole."}, {"e": "When a fish bites your tail, I will tell you."}, {"e": "Then the fish can’t see me."}, {"e": "He tried not to think."}, {"e": "Bear did not move."}], "passage": ["Fox went to another part of the lake. The water was not deep there. Fox said, “Here! Make a hole here.” Bear made a hole in the ice. Then he put his tail in the hole. Fox said, “Good! Now wait. Don’t move. Don’t think. Fish can hear you think.” “OK,” said Bear. He tried not to think. Fox said, “I will watch the hole. When a fish bites your tail, I will tell you. I will say, ‘Now, Bear!’ Then pull your tail out.” Bear did not answer. He was trying not to think. Fox said, “I will wait behind those trees. Then the fish can’t see me.” Fox went behind the trees. Bear did not move. Fox laughed and laughed. Then he ate his fish and went home."], "qa": [["Where did Fox tell Bear to make a hole?", "In another part of the lake where the water is not deep"], ["What did Bear do with his tail?", "He put it in the hole in the ice."], ["What did Fox tell Bear not to do?", "Because Fox said fish can hear him think"], ["When will Fox say, “Now, Bear!”?", "When a fish bites Bear’s tail"], ["Why did Bear not answer Fox?", "Because he was trying not to think"], ["Where will Fox wait?", "He will wait behind some trees."], ["What did Fox do behind the trees?", "He laughed and laughed, ate fish, then went home."]], "ox": [["The water was not deep where Bear made a hole.", true], ["Fox told Bear to think a lot.", false], ["Bear put his tail in the hole.", true], ["Fox waited behind the trees.", true], ["Fox helped Bear catch a fish.", false]]}, "23": {"title": "How Bear Lost His Tail", "vocab": [{"w": "wake up", "k": "(잠에서) 깨다", "d": "to stop sleeping", "s": [["What time do you usually wake up in the morning?", "wake up"]]}, {"w": "still", "k": "여전히", "d": "even now; continuing", "s": [["Bear was still sitting by the hole.", "still"]]}, {"w": "covered", "k": "–이 덮인", "d": "having something over the top", "s": [["He was covered with snow.", "covered"], ["The floor is covered with a red carpet.", "covered"]]}, {"w": "yell", "k": "소리치다", "d": "to shout loudly", "s": [["Fox yelled, “Now, Bear!”", "yelled"]]}, {"w": "frozen", "k": "얼어붙은", "d": "turned into ice", "s": [["It was frozen in the ice!", "frozen"]]}, {"w": "today", "k": "오늘, 현재", "d": "now; these days", "s": [["Today, bears do not have tails.", "Today"], ["Maybe bears today remember their tails,  and that makes them sad.", "today"], ["Maybe bears today remember their tails, and that makes them sad.", "today"]]}, {"w": "also", "k": "–도", "d": "too", "s": [["They also make sad noises in the woods.", "also"]]}, {"w": "noise", "k": "(듣기 싫은) 소리", "d": "a loud, unpleasant sound", "s": [["They also make sad noises in the woods.", "noises"]]}, {"w": "woods", "k": "숲", "d": "an area with many trees", "s": [["They also make sad noises in the woods.", "woods"]]}, {"w": "maybe", "k": "어쩌면", "d": "perhaps", "s": [["Maybe bears today remember their tails,  and that makes them sad.", "Maybe"], ["Maybe bears today remember their tails, and that makes them sad.", "Maybe"]]}], "sentences": [{"e": "That night, it snowed a lot.", "k": "그날 밤, 눈이 많이 내렸습니다."}, {"e": "Bear was still sitting by the hole.", "k": "곰은 여전히 구멍 옆에 앉아 있었습니다."}, {"e": "He was covered with snow.", "k": "그는 눈으로 덮여 있었습니다."}, {"e": "Fox knew Bear was sleeping under the snow.", "k": "여우는 곰이 눈 밑에서 자고 있다는 것을 알았습니다."}, {"e": "Fox saw a big white hill."}, {"e": "He thought he had a fish."}, {"e": "Today, bears do not have tails."}, {"e": "Maybe bears today remember their tails, and that makes them sad."}, {"e": "It was frozen in the ice!"}, {"e": "But Fox just ran away."}], "passage": ["That night, it snowed a lot. In the morning, Fox woke up. He thought, “Where is Bear? Did he go home?” Fox went to the lake. Fox saw a big white hill. It was Bear! Bear was still sitting by the hole. He was covered with snow. Fox went to Bear. He listened. Fox knew Bear was sleeping under the snow. Fox yelled, “Now, Bear!” Bear jumped up! Snap! Bear turned to the hole. He thought he had a fish. Bear saw his tail. It was frozen in the ice!", "Bear was very mad. He yelled, “Fox! You did this to me!” Fox was rolling on the ice. He was laughing and laughing. Bear tried to hit Fox. But Fox just ran away. Today, bears do not have tails. They do not like foxes. They also make sad noises in the woods. Maybe bears today remember their tails, and that makes them sad."], "qa": [["What happened in the night?", "It snowed a lot."], ["What did Fox see when he went to the lake?", "He saw a big white hill."], ["What was Bear doing under the snow?", "He was sleeping."], ["What did Bear see after he jumped up?", "He saw his tail frozen in the ice!"], ["How did Bear feel?", "He was very mad."], ["What was Fox doing?", "He was rolling on the ice laughing and laughing."], ["What did Bear try to do?", "He tried to hit Fox."], ["What do bears not have today?", "They do not have tails."], ["Why might bears make sad noises in the woods?", "They might remember their tails, and that makes them sad."]], "ox": [["It snowed a lot that night.", true], ["Bear went home before the morning.", false], ["Bear’s tail was frozen in the ice.", true], ["Fox was sorry for Bear.", false], ["Today, bears do not have tails.", true]]}, "24": {"title": "Mom's Diet", "vocab": [{"w": "on a diet", "k": "다이어트를 하다", "d": "eating less to lose weight", "s": [["I’m far too fat, and I’m going on a diet.", "on a diet"]]}, {"w": "get sick of", "k": "싫증이 나다", "d": "to become tired of something", "s": [["We got sick of lettuce and tomatoes.", "got sick of"]]}, {"w": "pleased", "k": "기쁜", "d": "happy", "s": [["You’ll be pleased.", "pleased"]]}, {"w": "gobble down", "k": "–을 급하게 먹다", "d": "to eat very quickly", "s": [["I’m not sitting here and watching you two  gobble down spaghetti.", "gobble down"]]}, {"w": "fridge", "k": "냉장고", "d": "a machine that keeps food cold", "s": [["What’s in your fridge, Dad?", "fridge"]]}, {"w": "reply", "k": "대답하다", "d": "to answer", "s": [["“Is she ever!” we replied.", "replied"]]}, {"w": "scale", "k": "체중계", "d": "a machine that tells how heavy you are", "s": [["Every morning, Mom got on the scales.", "scales"]]}, {"w": "give in", "k": "항복하다, 손들다", "d": "to stop fighting and agree", "s": [["I had to give in!", "give in"]]}, {"w": "cheer", "k": "환호, 응원", "d": "a shout of happiness", "s": [["Three cheers!", "cheers"]]}, {"w": "cuddly", "k": "꼭 껴안고 싶은", "d": "nice to hug", "s": [["You’re a cuddly mother.", "cuddly"]]}], "sentences": [{"e": "I’m far too fat, and I’m going on a diet."}, {"e": "We got sick of lettuce and tomatoes."}, {"e": "You’ll be pleased."}, {"e": "I’m not sitting here and watching you two  gobble down spaghetti."}, {"e": "What’s in your fridge, Dad?"}, {"e": "“Is she ever!” we replied."}, {"e": "Every morning, Mom got on the scales."}, {"e": "I had to give in!"}, {"e": "Three cheers!"}, {"e": "You’re a cuddly mother."}], "passage": [], "qa": [["What does Mom think?", "She thinks she is too fat."], ["Do the children think that?", "No, they do not think Mom is fat."], ["What will Mom do?", "She will go on a diet."], ["What did they eat?", "They ate lettuce and tomatoes."], ["When did they eat lettuce and tomatoes?", "They ate them every day for every meal."], ["What will they eat the next day?", "They will eat parsley and carrots."], ["Are they happy to eat parsley and carrots?", "No, they are not."], ["What do the children want to eat?", "They want to eat spaghetti."], ["Where did the children go?", "To Dad’s house"], ["What do the children want?", "They want Dad’s food."], ["When Mom says she is fat, what do the children say?", "They say she is not fat; she is just right."], ["What did the children smell?", "They smelled spaghetti and doughnuts."], ["How do the children like Mom?", "They like her just as she is."], ["What does Mom think about herself?", "She likes herself, too."]], "ox": [["Mom thinks she is too fat.", true], ["The children think Mom is fat.", false], ["They ate lettuce and tomatoes every day.", true], ["The children want to eat spaghetti.", true], ["In the end, Mom does not like herself.", false]]}};
